'use strict';
(function(root){function wave(p,x,y,angle,t,size=110,color='#e7b69d'){if(t<0||t>.7)return;p.save();p.globalAlpha*=1-t/.7;p.translate(x,y);p.rotate(angle);p.strokeStyle=color;p.lineWidth=4;p.beginPath();p.moveTo(size*t*2,-size*.45);p.lineTo(size*t*2+20,-size*.12);p.lineTo(size*t*2+7,size*.12);p.lineTo(size*t*2+20,size*.45);p.stroke();p.restore();}
function amp(p,x,y,t){p.save();p.translate(x,y);const shake=Math.sin(t*45)*1.5;p.fillStyle='#101517';p.fillRect(-34,-90,68,90);p.fillStyle='#433b3c';p.fillRect(-28,-83,56,76);p.fillStyle='#181d1d';for(let i=0;i<2;i++){p.beginPath();p.arc(shake,-63+i*36,15,0,Math.PI*2);p.fill();p.strokeStyle='#817773';p.lineWidth=2;p.stroke();}p.fillStyle='#d34e40';p.fillRect(-26,-88,9,3);p.restore();}
function draw(p,f,t){if(f.heroId!==6||f.cell!==5)return false;if(t<0||t>3)return true;const o=f.from||f,ox=o.x,oy=o.y-20,angle=Math.atan2(f.y-o.y,f.x-o.x);if(f.phase){if(f.metalKind==='stomp')root.RPG_SKILL_FX?.sheet(p,'dust',t,.55,f.x,f.y+2,115,55);else{root.RPG_SKILL_FX?.sheet(p,f.metalKind==='riff-finish'?'shock':'punch',t,.5,f.x,f.y-18,f.metalKind==='riff-finish'?110:55,65);if(f.metalKind==='riff-finish')root.RPG_SKILL_FX?.earth(p,f.x,f.y,t,85,2);}return true;}
if(f.slot===0)wave(p,ox+15,oy,angle,t,140);if(f.slot===1)for(let i=0;i<3;i++)root.RPG_SKILL_FX?.sheet(p,'dust',t-i*.16,.6,ox+(i-1)*30,oy+25,55,30);if(f.slot===2){p.save();p.globalAlpha*=Math.max(0,1-t/1.5);p.strokeStyle='#c2b6e2';p.lineWidth=2;for(let i=0;i<3;i++){p.beginPath();p.moveTo(ox-25,oy+i*6);p.lineTo(ox-12,oy-10+i*6);p.lineTo(ox+4,oy+7+i*6);p.lineTo(ox+20,oy-4+i*6);p.stroke();}p.restore();}if(f.slot===3){for(let i=0;i<6;i++)wave(p,ox,oy,angle,t-.25-i*.25,100,'#ed8d72');}return true;}
function state(p,g,time){if(g.s.active!==6||g.h.cell!==5||!g.c.metal)return;const m=g.c.metal,c=g.c;if(m.amp>0){amp(p,c.x-55,c.y,time);amp(p,c.x+55,c.y,time);}if(m.basic)wave(p,m.basic.from.x,m.basic.from.y-20,Math.atan2(m.basic.y-m.basic.from.y,m.basic.x-m.basic.from.x),time-m.basic.at,65,'#c3b5a2');if(m.feedback>0){p.save();p.strokeStyle='#c9a8ef';p.lineWidth=2;p.beginPath();for(let i=0;i<8;i++){const x=c.x-22+i*6,y=c.y-30+Math.sin(time*18+i*2)*7;i?p.lineTo(x,y):p.moveTo(x,y);}p.stroke();p.restore();}p.save();p.fillStyle='#efc892';p.font='bold 10px sans-serif';p.textAlign='center';p.fillText('열광 '+m.heat+'/10',c.x,c.y-72);p.restore();}
function weaponSprite(){const canvas=document.createElement('canvas');canvas.width=64;canvas.height=64;const p=canvas.getContext('2d');p.imageSmoothingEnabled=false;const poly=(color,points)=>{p.fillStyle=color;p.beginPath();points.forEach(([x,y],i)=>i?p.lineTo(x,y):p.moveTo(x,y));p.closePath();p.fill();};poly('#100f17',[[4,30],[21,31],[43,12],[43,7],[57,2],[62,7],[52,20],[47,20],[30,38],[32,58],[7,61],[18,43]]);poly('#dc354c',[[7,33],[22,35],[29,39],[29,55],[11,57],[22,42]]);poly('#262630',[[13,36],[23,38],[26,42],[26,51],[17,53],[25,41]]);poly('#815b47',[[24,35],[46,13],[50,17],[28,39]]);poly('#dd334b',[[46,9],[56,5],[58,8],[51,16],[47,16]]);p.strokeStyle='#dbd3c4';p.lineWidth=1;for(let i=0;i<3;i++){p.beginPath();p.moveTo(19+i,48);p.lineTo(53+i,10);p.stroke();}p.fillStyle='#b6bcc9';p.fillRect(19,44,7,3);p.fillRect(24,38,5,3);p.fillStyle='#e9bf66';p.fillRect(29,46,2,2);p.fillRect(29,50,2,2);for(let i=0;i<3;i++){p.fillStyle='#b6bcc9';p.fillRect(45+i*3,6-i,2,2);}return {canvas,ax:32,ay:64};}
root.RPG_METAL_FX={draw,state,weaponSprite};})(typeof window!=='undefined'?window:globalThis);
